using System;using System.IO;using System.Text;using System.Linq;using System.Threading;using System.Diagnostics;using System.Collections.Generic;
namespace GearLab {
 public static class Wave56FastTests {
  public static int Run(string folder){Directory.CreateDirectory(folder);try{var seconds=new List<double>();var counts=new List<int>();int workers=CADKernel.StartedWorkers;foreach(int ratio in new[]{17,30,50}){var w=Stopwatch.StartNew();var p=Engine.Starter(4);p.Ratio=ratio;p.Radius=Math.Max(p.Radius,WaveFastModel.MinimumRadius(p)+.1);Engine.FitOverall(p);var r=Engine.Calculate(p);if(!r.Valid)throw new Exception(string.Join(";",r.Errors));r.Model=CadBuilder.Build(r);if(!r.Model.Valid)throw new Exception(string.Join(";",r.Model.Errors));var meshes=r.Model.Parts.Select(x=>SceneMesher.Build(x,CancellationToken.None)).ToArray();if(meshes.Length<17||meshes.Any(x=>x.Triangles==0||x.SignedVolume()<=0))throw new Exception("Empty or open preview geometry");seconds.Add(w.Elapsed.TotalSeconds);counts.Add(meshes.Sum(x=>x.Triangles));if(w.Elapsed.TotalSeconds>3)throw new Exception("Preview exceeded 3 seconds");}if(CADKernel.StartedWorkers!=workers)throw new Exception("Preview started a native worker");File.WriteAllText(Path.Combine(folder,"fast-preview-results.json"),CADDocument.Serializer().Serialize(new{ratios=new[]{17,30,50},preview_seconds=seconds.ToArray(),triangles=counts.ToArray(),native_workers=CADKernel.StartedWorkers-workers}),Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"fast-preview-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
